def running_median(stream):
    lower = []  # max heap (negated)
    higher = []  # min heap

    for num in stream:
        if not lower or num <= -lower[0]:
            heapq.heappush(lower, -num)
        else:
            heapq.heappush(higher, num)

        # Rebalance
        if len(lower) > len(higher) + 1:
            heapq.heappush(higher, -heapq.heappop(lower))
        elif len(higher) > len(lower):
            heapq.heappush(lower, -heapq.heappop(higher))

